      setCurrentSlide(p => (p + 1) % (slides.length || 1));
    }, 9000);
    return () => clearInterval(interval);
  }, [slides, currentSlide]);

  useEffect(() => {
    const interval = setInterval(() => {
      if (reviews.length > 0) {
        setCurrentReviewIndex(prev => (prev + 1) % reviews.length);
      }
