Se os valores do formulário não estão chegando, você **DEVE** seguir estes passos exatamente. O Google exige que você aprove manualmente o script para enviar e-mails.

## 1. Atualizar o Código (Versão v1.6 Ultra-Robusta)
Substitua o código atual no seu editor de Apps Script por este:

```javascript
/**
 * Google Apps Script - Rosimeire Serviços v1.6
 * Sincronização + Motor de Envio de E-mails com Debug
 */

function doGet() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Database");
  if (!sheet) return ContentService.createTextOutput("Erro: Aba 'Database' não encontrada").setMimeType(ContentService.MimeType.TEXT);

  const values = sheet.getRange(2, 1, 1, 13).getValues()[0]; 
  const data = {
    slides: JSON.parse(values[0] || "[]"),
    siteConfig: JSON.parse(values[1] || "{}"),
    sectionImages: JSON.parse(values[2] || "{}"),
    socialLinks: JSON.parse(values[3] || "{}"),
    emailConfig: JSON.parse(values[4] || "{}"),
    notices: JSON.parse(values[5] || "[]"),
    reviews: JSON.parse(values[6] || "[]"),
    partners: JSON.parse(values[7] || "[]"),
    googleMapsLink: values[8] || "",
    contactPhone: values[9] || "",
    addressDetail: values[10] || "",
    adminUsername: values[11] || "admin",
    adminPassword: values[12] || "rosimeire2025"
  };

  return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  let payload;
  try {
    payload = JSON.parse(e.postData.contents);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: "JSON Inválido" })).setMimeType(ContentService.MimeType.JSON);
  }

  // AÇÃO: Envio de Contacto
  if (payload.action === 'send_contact') {
    try {
      const formData = payload.formData || {};
      const name = formData.name || "Não informado";
      const email = formData.email || "Não informado";
      const phone = formData.phone || "Não informado";
      const message = formData.message || "Sem mensagem";
      const recipient = payload.recipient || "atendimento@rosimeireservicos.com";

      const subject = "Website: Nova Mensagem de " + name;
      const htmlBody = `
        <div style="font-family: sans-serif; color: #333; line-height: 1.6;">
          <h2 style="color: #081221; border-bottom: 2px solid #f8c8c4; padding-bottom: 10px;">Novo Contacto via Website</h2>
          <p><strong>Nome:</strong> ${name}</p>
          <p><strong>E-mail:</strong> ${email}</p>
          <p><strong>Telefone:</strong> ${phone}</p>
          <div style="background: #f9f9f9; padding: 15px; border-left: 4px solid #f8c8c4; margin-top: 20px;">
            <strong>Mensagem:</strong><br>
            ${message.replace(/\n/g, '<br>')}
          </div>
          <p style="font-size: 10px; color: #999; margin-top: 30px;">Enviado pelo Sistema Integrado Rosimeire (SIR)</p>
        </div>
      `;

      // Envia usando o GmailApp para maior compatibilidade
      GmailApp.sendEmail(recipient, subject, "", { htmlBody: htmlBody });

      return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
    } catch (err) {
      return ContentService.createTextOutput(JSON.stringify({ status: "error", details: err.toString() })).setMimeType(ContentService.MimeType.JSON);
    }
  }

  // AÇÃO PADRÃO: Salvar Dados
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Database");
  if (payload && sheet) {
    const row = [
      JSON.stringify(payload.slides || []),
      JSON.stringify(payload.siteConfig || {}),
      JSON.stringify(payload.sectionImages || {}),
      JSON.stringify(payload.socialLinks || {}),
      JSON.stringify(payload.emailConfig || {}),
      JSON.stringify(payload.notices || []),
      JSON.stringify(payload.reviews || []),
      JSON.stringify(payload.partners || []),
      payload.googleMapsLink || "",
      payload.contactPhone || "",
      payload.addressDetail || "",
      payload.adminUsername || "admin",
      payload.adminPassword || "rosimeire2025"
    ];
    sheet.getRange(2, 1, 1, 13).setValues([row]);
  }

  return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
}
```

## 2. O PASSO MAIS IMPORTANTE: AUTORIZAÇÃO
Depois de colar o código acima:
1. No editor do script, no menu superior, selecione a função **`doGet`** no seletor ao lado de "Executar".
2. Clique no botão **Executar** (ícone de play).
3. Uma janela aparecerá: "Autorização necessária". Clique em **Revisar permissões**.
4. Escolha sua conta Google.
5. Uma tela de "O Google não verificou este app" aparecerá (normal para scripts privados).
6. Clique em **Configurações avançadas** (no canto inferior esquerdo).
7. Clique no link lá embaixo que diz **Acessar [Nome do seu projeto] (não seguro)**.
8. Na última tela, clique em **Permitir**.
9. **Importante:** Agora clique em **Implantar** > **Gerenciar Implantações** > Editar (Lápis) > Versão: **Nova Versão** > **Implantar**.

## 3. Verificar a Aba
Certifique-se que o nome da aba na sua Planilha Google é exatamente **`Database`** (com 'D' maiúsculo). Se estiver "Página 1", o script falhará.

