# Configuração do SIR Backend v1.8 (Proteção Contra Perda de Dados)

Esta versão inclui uma **Trava de Segurança** que impede que o site apague seus dados acidentalmente se a conexão falhar.

## 1. Atualizar o Código (v1.8 - Data Loss Protection)
Substitua o código no editor de Apps Script:

```javascript
/**
 * Google Apps Script - Rosimeire Serviços v1.8
 * Bridge de Dados + Data Loss Protection (DLP)
 */

function doGet() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Database");
  if (!sheet) return ContentService.createTextOutput("Erro: Aba 'Database' não encontrada").setMimeType(ContentService.MimeType.TEXT);

  const values = sheet.getRange(2, 1, 1, 13).getValues()[0]; 
  const data = {
    slides: JSON.parse(values[0] || "[]"),
    siteConfig: JSON.parse(values[1] || "{}"),
    sectionImages: JSON.parse(values[2] || "{}"),
    socialLinks: JSON.parse(values[3] || "{}"),
    emailConfig: JSON.parse(values[4] || "{}"),
    notices: JSON.parse(values[5] || "[]"),
    reviews: JSON.parse(values[6] || "[]"),
    partners: JSON.parse(values[7] || "[]"),
    googleMapsLink: values[8] || "",
    contactPhone: values[9] || "",
    addressDetail: values[10] || "",
    adminUsername: values[11] || "admin",
    adminPassword: values[12] || "rosimeire2025"
  };

  return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  let payload;
  try {
    payload = JSON.parse(e.postData.contents);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: "JSON Inválido" })).setMimeType(ContentService.MimeType.JSON);
  }

  // AÇÃO: Envio de Contacto
  if (payload.action === 'send_contact') {
    try {
      const formData = payload.formData || {};
      const config = payload.emailConfig || {};
      const name = formData.name || "Não informado";
      const email = formData.email || "Não informado";
      const phone = formData.phone || "Não informado";
      const message = formData.message || "Sem mensagem";
      const recipient = payload.recipient || config.recipientEmail || "atendimento@rosimeireservicos.com";

      const subject = "Website Rosimeire: Nova Mensagem de " + name;
      const htmlBody = `
        <div style="font-family: sans-serif; color: #333; line-height: 1.6; max-width: 600px; border: 1px solid #eee; padding: 20px; border-radius: 8px;">
          <h2 style="color: #081221; border-bottom: 2px solid #f8c8c4; padding-bottom: 10px;">Novo Contacto via Website</h2>
          <p><strong>Nome:</strong> ${name}</p>
          <p><strong>E-mail:</strong> ${email}</p>
          <p><strong>Telefone:</strong> ${phone}</p>
          <div style="background: #fdf2f2; padding: 15px; border-left: 4px solid #f8c8c4; margin-top: 20px;">
            <strong>Mensagem:</strong><br>
            ${message.replace(/\n/g, '<br>')}
          </div>
          <p style="font-size: 10px; color: #999; margin-top: 30px;">Enviado via SIR (Sistema Integrado Rosimeire).</p>
        </div>
      `;

      GmailApp.sendEmail(recipient, subject, "", { 
        htmlBody: htmlBody,
        replyTo: email,
        name: "Website Rosimeire"
      });

      return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
    } catch (err) {
      return ContentService.createTextOutput(JSON.stringify({ status: "error", details: err.toString() })).setMimeType(ContentService.MimeType.JSON);
    }
  }

  // AÇÃO PADRÃO: Salvar Dados (COM TRAVA DE SEGURANÇA)
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Database");

  // TRAVA: Só grava se houver pelo menos um slide e um nome de empresa válido no payload
  const hasValidSlides = payload.slides && payload.slides.length > 0;
  const hasValidConfig = payload.siteConfig && payload.siteConfig.companyName && payload.siteConfig.companyName.length > 2;

  if (payload && sheet && hasValidSlides && hasValidConfig) {
    const row = [
      JSON.stringify(payload.slides),
      JSON.stringify(payload.siteConfig),
      JSON.stringify(payload.sectionImages || {}),
      JSON.stringify(payload.socialLinks || {}),
      JSON.stringify(payload.emailConfig || {}),
      JSON.stringify(payload.notices || []),
      JSON.stringify(payload.reviews || []),
      JSON.stringify(payload.partners || []),
      payload.googleMapsLink || "",
      payload.contactPhone || "",
      payload.addressDetail || "",
      payload.adminUsername || "admin",
      payload.adminPassword || "rosimeire2025"
    ];
    sheet.getRange(2, 1, 1, 13).setValues([row]);
    return ContentService.createTextOutput(JSON.stringify({ status: "success", message: "Dados guardados com segurança" })).setMimeType(ContentService.MimeType.JSON);
  } else {
    // Se a trava ativou, retorna erro e NÃO altera a planilha
    return ContentService.createTextOutput(JSON.stringify({ 
      status: "blocked", 
      message: "Gravação impedida: O payload enviado parecia estar vazio ou corrompido. Dados preservados." 
    })).setMimeType(ContentService.MimeType.JSON);
  }
}
```

## 2. Instruções de Recuperação (Histórico)
Se os dados sumirem novamente por erro humano:
1. Abra a sua Planilha Google.
2. Vá a **Ficheiro** > **Histórico de versões** > **Ver histórico de versões**.
3. Selecione uma data/hora no passado.
4. Clique em **Restaurar esta versão**.

## 3. Implantar
Sempre que atualizar o código: **Implantar** > **Gerenciar Implantações** > **Editar** > Versão: **Nova Versão** > **Implantar**.

