# Configuração do SIR Backend v1.9 (Relay de E-mail & Segurança de Dados)

Esta versão unifica a **Trava de Segurança (DLP)** com um motor de e-mail que respeita os campos do seu Painel Administrativo.

## 1. Atualizar o Código (v1.9 - Professional Mail Relay)
Substitua o código no editor de Apps Script:

```javascript
/**
 * Google Apps Script - Rosimeire Serviços v1.9
 * Bridge de Dados + Data Loss Protection + Professional Mailer
 */

function doGet() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Database");
  if (!sheet) return ContentService.createTextOutput("Erro: Aba 'Database' não encontrada").setMimeType(ContentService.MimeType.TEXT);

  const values = sheet.getRange(2, 1, 1, 13).getValues()[0]; 
  const data = {
    slides: JSON.parse(values[0] || "[]"),
    siteConfig: JSON.parse(values[1] || "{}"),
    sectionImages: JSON.parse(values[2] || "{}"),
    socialLinks: JSON.parse(values[3] || "{}"),
    emailConfig: JSON.parse(values[4] || "{}"),
    notices: JSON.parse(values[5] || "[]"),
    reviews: JSON.parse(values[6] || "[]"),
    partners: JSON.parse(values[7] || "[]"),
    googleMapsLink: values[8] || "",
    contactPhone: values[9] || "",
    addressDetail: values[10] || "",
    adminUsername: values[11] || "admin",
    adminPassword: values[12] || "rosimeire2025"
  };

  return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  let payload;
  try {
    payload = JSON.parse(e.postData.contents);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: "JSON Inválido" })).setMimeType(ContentService.MimeType.JSON);
  }

  // AÇÃO: Envio de Contacto Profissional
  if (payload.action === 'send_contact') {
    try {
      const formData = payload.formData || {};
      const config = payload.emailConfig || {};

      const name = formData.name || "Não informado";
      const clientEmail = formData.email || "Não informado";
      const phone = formData.phone || "Não informado";
      const message = formData.message || "Sem mensagem";

      // Destinatário definido no Admin ou Fallback
      const recipient = config.recipientEmail || "atendimento@rosimeireservicos.com";

      const subject = "⚠️ NOVO CONTACTO WEBSITE: " + name;
      const htmlBody = `
        <div style="font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; color: #081221; line-height: 1.6; max-width: 600px; border: 1px solid #f8c8c4; border-radius: 4px; overflow: hidden;">
          <div style="background: #081221; padding: 25px; text-align: center;">
            <h2 style="color: #f8c8c4; margin: 0; text-transform: uppercase; letter-spacing: 2px; font-size: 18px;">Rosimeire Serviços</h2>
            <p style="color: rgba(255,255,255,0.6); margin: 5px 0 0 0; font-size: 10px; text-transform: uppercase; letter-spacing: 4px;">Protocolo de Atendimento</p>
          </div>

          <div style="padding: 30px; background: white;">
            <p style="font-size: 14px; border-bottom: 1px solid #eee; padding-bottom: 10px;"><strong>Cliente:</strong> ${name}</p>
            <p style="font-size: 14px; border-bottom: 1px solid #eee; padding-bottom: 10px;"><strong>E-mail:</strong> <a href="mailto:${clientEmail}">${clientEmail}</a></p>
            <p style="font-size: 14px; border-bottom: 1px solid #eee; padding-bottom: 10px;"><strong>Contacto:</strong> ${phone}</p>

            <div style="margin-top: 25px; padding: 20px; background: #fdf2f2; border-left: 4px solid #f8c8c4; border-radius: 2px;">
              <strong style="display: block; margin-bottom: 10px; font-size: 12px; color: #666; text-transform: uppercase;">Mensagem Recebida:</strong>
              <div style="font-style: italic; color: #333; font-size: 15px;">${message.replace(/\n/g, '<br>')}</div>
            </div>
          </div>

          <div style="background: #f9f9f9; padding: 15px; text-align: center; border-top: 1px solid #eee;">
            <p style="font-size: 10px; color: #999; margin: 0;">Enviado em: ${new Date().toLocaleString('pt-PT')}</p>
            <p style="font-size: 9px; color: #ccc; margin: 5px 0 0 0;">SIR Backend v1.9 - Todos os direitos reservados</p>
          </div>
        </div>
      `;

      /**
       * Nota sobre SMTP: 
       * O Google Apps Script não conecta via SMTP Externo em tempo real de execução.
       * Ele utiliza a conta do proprietário da planilha como gateway.
       * No entanto, configuramos o 'replyTo' para que ao clicar em responder, você fale com o cliente.
       */
      GmailApp.sendEmail(recipient, subject, "", { 
        htmlBody: htmlBody,
        replyTo: clientEmail,
        name: "Website Rosimeire Serviços"
      });

      return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
    } catch (err) {
      return ContentService.createTextOutput(JSON.stringify({ status: "error", details: err.toString() })).setMimeType(ContentService.MimeType.JSON);
    }
  }

  // AÇÃO PADRÃO: Salvar Dados (COM TRAVA DE SEGURANÇA DLP)
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Database");
  const hasValidSlides = payload.slides && payload.slides.length > 0;
  const hasValidConfig = payload.siteConfig && payload.siteConfig.companyName && payload.siteConfig.companyName.length > 2;

  if (payload && sheet && hasValidSlides && hasValidConfig) {
    const row = [
      JSON.stringify(payload.slides),
      JSON.stringify(payload.siteConfig),
      JSON.stringify(payload.sectionImages || {}),
      JSON.stringify(payload.socialLinks || {}),
      JSON.stringify(payload.emailConfig || {}),
      JSON.stringify(payload.notices || []),
      JSON.stringify(payload.reviews || []),
      JSON.stringify(payload.partners || []),
      payload.googleMapsLink || "",
      payload.contactPhone || "",
      payload.addressDetail || "",
      payload.adminUsername || "admin",
      payload.adminPassword || "rosimeire2025"
    ];
    sheet.getRange(2, 1, 1, 13).setValues([row]);
    return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
  } else {
    return ContentService.createTextOutput(JSON.stringify({ status: "blocked", message: "Erro de integridade no payload." })).setMimeType(ContentService.MimeType.JSON);
  }
}
```

## 2. Instruções Finais
1. Copie o código acima para o seu script.
2. Clique em **Executar** (`doGet`) para autorizar permissões de e-mail.
3. **Implantar** > **Gerenciar Implantações** > **Editar** > Versão: **Nova Versão** > **Implantar**.

Desta forma, os dados que você inserir no painel SMTP (especialmente o e-mail de recebimento) serão utilizados para direcionar as mensagens do site.

