    if (internalViews.includes(link as View)) {
      setView(link as View);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else if (link.startsWith('http')) {
      window.open(link, '_blank');
    } else if (link.startsWith('#')) {
