      console.error("Segurança: Tentativa de publicar dados vazios bloqueada.");
      alert("Erro de Segurança: Os dados atuais parecem estar vazios. Recarregue a página antes de guardar.");
      return false;
    }

    setIsSyncing(true);
    setCloudStatus('loading');
    try {
