                    <button onClick={() => removePartner(p.id)} className="absolute top-4 right-4 text-red-500/30 hover:text-red-500 transition-colors"><Trash2 size={14}/></button>
                    <div className="h-32 bg-white/5 rounded-sm flex items-center justify-center overflow-hidden">
                       {p.logo ? <img src={p.logo} className="h-full w-full object-contain grayscale opacity-50" /> : <ImageIcon size={24} className="opacity-10" />}
                    </div>
                    <div className="space-y-4">
                       <div>
                          <label className="admin-label">Nome Parceiro</label>
                          <input value={p.name} onChange={e => updatePartner(p.id, 'name', e.target.value)} className="admin-input" />
                       </div>
                       <div>
                          <label className="admin-label">URL do Logótipo</label>
                          <input value={p.logo} onChange={e => updatePartner(p.id, 'logo', e.target.value)} className="admin-input text-[10px]" />
                       </div>
                       <div>
                          <label className="admin-label">Link Externo</label>
                          <input value={p.url} onChange={e => updatePartner(p.id, 'url', e.target.value)} className="admin-input text-[10px]" />
                       </div>
                    </div>
                  </div>
                ))}
              </div>
              <button onClick={addPartner} className="admin-btn-add"><Plus size={16}/> Adicionar Novo Parceiro de Prestígio</button>
            </div>
          )}

          {activeTab === 'user' && (
