          <div className="flex gap-6 items-center">
            <button onClick={onLogout} className="text-[10px] font-bold tracking-widest uppercase text-white/40 hover:text-white transition-colors">Sair</button>
            <button onClick={onClose} className="text-white/20 hover:text-white transition-colors ml-4"><X size={32}/></button>
          </div>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-8 gap-4 mb-16">
          {[
            { id: 'site', icon: <Layout size={14}/>, label: 'Geral' },
            { id: 'slides', icon: <ImageIcon size={14}/>, label: 'Slides' },
            { id: 'images', icon: <Palette size={14}/>, label: 'Visual' },
            { id: 'email', icon: <Mail size={14}/>, label: 'E-mail / Redes' },
            { id: 'notices', icon: <Bell size={14}/>, label: 'Avisos' },
            { id: 'reviews', icon: <Star size={14}/>, label: 'Legado' },
            { id: 'partners', icon: <Briefcase size={14}/>, label: 'Parceiros' },
            { id: 'user', icon: <User size={14}/>, label: 'Conta' }
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`p-6 text-[10px] font-bold tracking-[0.3em] uppercase transition-all flex flex-col items-center justify-center gap-4 rounded-sm border ${activeTab === tab.id ? 'text-[#f8c8c4] border-[#f8c8c4] bg-[#f8c8c4]/5 shadow-[0_0_20px_rgba(248,200,196,0.1)]' : 'text-white/20 border-white/5 bg-white/[0.01] hover:text-white/40'}`}>
              {tab.icon}
              <span className="text-center">{tab.label}</span>
            </button>
          ))}
        </div>

        <div className="min-h-[50vh]">
          {activeTab === 'site' && (
            <div className="space-y-12 max-w-5xl mx-auto">
              <div className="crystal-card p-12 space-y-10 border-[#f8c8c4]/30 bg-gradient-to-br from-[#f8c8c4]/5 to-transparent relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-12 text-[#f8c8c4]/10"><Wand2 size={120} strokeWidth={0.5} /></div>
                <div className="flex items-center gap-6 text-[#f8c8c4]"><Sparkles size={24}/><h3 className="text-xl font-bold tracking-widest uppercase text-white">Eventos Mágicos (IA)</h3></div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-12 relative z-10">
                   <div className="space-y-6">
                      <label className="admin-label">Descreva o efeito visual desejado</label>
                      <textarea value={magicEffect.prompt} onChange={e => updateMagicEffect('prompt', e.target.value)} placeholder="Ex: Neve rosa caindo suavemente..." className="admin-input !bg-white/5 min-h-[120px]" />

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                        <div>
                          <label className="admin-label !mb-2 flex items-center gap-2"><Calendar size={10}/> Data de Início</label>
                          <input type="date" value={magicEffect.startDate} onChange={e => updateMagicEffect('startDate', e.target.value)} className="admin-input !py-4 !bg-white/10 !border-[#f8c8c4]/20" />
                        </div>
                        <div>
                          <label className="admin-label !mb-2 flex items-center gap-2"><Calendar size={10}/> Data de Fim</label>
                          <input type="date" value={magicEffect.endDate} onChange={e => updateMagicEffect('endDate', e.target.value)} className="admin-input !py-4 !bg-white/10 !border-[#f8c8c4]/20" />
                        </div>
                      </div>

                      <button onClick={handleGenerateMagic} disabled={isMagicLoading || !magicEffect.prompt} className="btn-serenity !py-6 flex items-center gap-4 w-full justify-center text-[10px] font-black tracking-[0.4em]">
                        {isMagicLoading ? <Loader2 size={16} className="animate-spin" /> : <Wand2 size={16} />} GERAR MAGIA COM IA
                      </button>
                   </div>

                   <div className="space-y-6 bg-white/[0.02] border border-white/5 p-8 rounded-sm">
                      {magicEffect.active ? (
                        <div className="space-y-6">
                           <div className="flex items-center justify-between">
                              <div className="flex flex-col gap-1">
                                <div className="flex items-center gap-4 text-white/40"><Clock size={12}/><span className="text-[9px] font-bold uppercase tracking-widest">Início: {new Date(magicEffect.startDate).toLocaleDateString()}</span></div>
                                <div className="flex items-center gap-4 text-white/40"><Calendar size={12}/><span className="text-[9px] font-bold uppercase tracking-widest">Fim: {new Date(magicEffect.endDate).toLocaleDateString()}</span></div>
                              </div>
                              <span className={`px-3 py-1 text-[8px] font-black uppercase tracking-widest rounded-full ${new Date() < new Date(magicEffect.startDate) ? 'bg-blue-500/10 text-blue-400' : 'bg-green-500/10 text-green-400'}`}>
                                {new Date() < new Date(magicEffect.startDate) ? 'AGENDADO' : 'ATIVO'}
                              </span>
                           </div>
                           <p className="text-[10px] text-white/30 italic leading-relaxed">O efeito visual será exibido no site dentro do intervalo agendado.</p>
                           <button onClick={handleDeactivateMagic} className="w-full py-4 border border-red-500/20 text-red-400 text-[9px] font-bold tracking-[0.4em] uppercase hover:bg-red-500/10 transition-colors flex items-center justify-center gap-4">
                             <Trash2 size={14} /> DESATIVAR EVENTO
                           </button>
                        </div>
                      ) : (
                        <div className="flex flex-col items-center justify-center py-10 opacity-20 gap-4">
