          setAddressDetail(data.addressDetail || 'R. 25 de Abril 49, 8125-234, Quarteira, Faro Algarve – Portugal');
        }
        setCloudStatus('connected');
        return data;
      }
      setCloudStatus('error');
      return null;
    } catch (err) {
