const MagicEffectRunner = ({ manager }: { manager?: MagicEffectManager }) => {
  useEffect(() => {
    const styleId = 'dynamic-magic-effect-style';
    const cleanup = () => { const el = document.getElementById(styleId); if (el) el.innerHTML = ''; };
    if (!manager || !manager.activeId || !manager.items) { cleanup(); return; }
    const activeItem = manager.items.find(i => i.id === manager.activeId);
    if (!activeItem || !activeItem.code) { cleanup(); return; }
    let styleElement = document.getElementById(styleId);
    if (!styleElement) { styleElement = document.createElement('style'); styleElement.id = styleId; document.head.appendChild(styleElement); }
    styleElement.innerHTML = activeItem.code;
    return cleanup;
  }, [manager]);
  return <div className="magic-event-layer fixed inset-0 z-[9999] pointer-events-none overflow-hidden select-none" aria-hidden="true" />;
};

