            <section id="home" className="min-h-screen h-screen relative flex overflow-hidden group/hero pt-32">
              <AnimatePresence mode="wait">
                <motion.div key={currentSlide} initial={{ opacity: 0, scale: 1.05 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0 }} transition={{ duration: 2 }} className="absolute inset-0">
                  <div className="absolute inset-0 bg-cover bg-center" style={{ backgroundImage: `url(${slides[currentSlide]?.image})` }} />
                  <div className="absolute inset-0 bg-gradient-to-r from-[#081221] via-[#081221]/60 to-transparent" />
                </motion.div>
              </AnimatePresence>
              <div className="container mx-auto px-8 md:px-32 relative z-10 flex flex-col justify-center h-full">
                <motion.div key={`c-${currentSlide}`} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="flex flex-col max-w-4xl text-left">
                  <span className="tagline mb-3 block">{slides[currentSlide]?.tag}</span>
                  <h1 className="heading-serif text-4xl md:text-6xl lg:text-[5.5rem] text-white mb-5 leading-[1.1] uppercase tracking-tighter">
                    {slides[currentSlide]?.title.split(' ')[0]}<br/>
                    <span className="italic font-light opacity-60 text-[#f8c8c4]">{slides[currentSlide]?.title.split(' ').slice(1).join(' ')}</span>
                  </h1>
                  <p className="text-xs md:text-lg font-light text-white/50 max-w-lg leading-relaxed mb-8">{slides[currentSlide]?.description}</p>
                  <button onClick={() => setView('contact')} className="btn-serenity !px-8 !py-3 w-fit">{slides[currentSlide]?.buttonText || t.navContact}</button>
                </motion.div>
              </div>
            </section>

            <section id="services" className="py-32 md:py-64 relative bg-[#040911]/10">
              <div className="container mx-auto px-8 md:px-16">
                <div className="flex flex-col md:flex-row justify-between items-start mb-32 gap-16">
                   <div className="max-w-3xl">
                     <span className="tagline mb-10 block">{t.servicesTitle}</span>
                     <h2 className="heading-serif text-6xl md:text-[9rem] text-white leading-none">{t.servicesSubtitle}</h2>
                   </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                  {[
                    { title: t.s1Title, tagline: t.s1Tagline, desc: t.s1Desc, icon: <Building2 size={32}/> },
                    { title: t.s2Title, tagline: t.s2Tagline, desc: t.s2Desc, icon: <Home size={32}/> },
                    { title: t.s3Title, tagline: t.s3Tagline, desc: t.s3Desc, icon: <Sparkle size={32}/> },
                    { title: t.s4Title, tagline: t.s4Tagline, desc: t.s4Desc, icon: <Paintbrush size={32}/> }
                  ].map((s, idx) => (
                    <div key={idx} className="crystal-card p-14 rounded-sm flex flex-col min-h-[500px] justify-between">
                       <div className="space-y-10">
                         <div className="text-[#f8c8c4]/60">{s.icon}</div>
                         <h3 className="text-3xl font-light text-white tracking-tighter uppercase">{s.title}</h3>
                         <p className="text-[#f8c8c4]/80 text-[11px] font-bold uppercase tracking-[0.4em] italic">{s.tagline}</p>
                         <p className="text-white/50 text-base font-light leading-relaxed">{s.desc}</p>
                       </div>
                    </div>
                  ))}
                </div>
              </div>
            </section>
          </motion.div>
        )}

        {view === 'careers' && (
          <motion.div key="careers" initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} className="pt-56 pb-64">
            <div className="container mx-auto px-8 md:px-16 lg:px-32">
              <button onClick={() => setView('home')} className="flex items-center gap-4 text-[10px] font-bold uppercase tracking-[0.4em] text-white/20 hover:text-[#f8c8c4] transition-all mb-16 group"><ArrowLeft size={16} /> {t.back}</button>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-24 items-center mb-40">
                <div className="space-y-10">
                   <h2 className="heading-serif text-6xl md:text-8xl text-white uppercase leading-none">{t.careersHeroTitle}</h2>
                   <p className="text-xl md:text-2xl font-light text-white/60 leading-relaxed max-w-xl">{t.careersHeroSubtitle}</p>
                   <div className="w-24 h-[1px] bg-[#f8c8c4]" />
                </div>
                <div className="relative group overflow-hidden rounded-sm">
                  <img src={sectionImages.careers} className="w-full h-[600px] object-cover grayscale group-hover:grayscale-0 transition-all duration-1000" />
                </div>
              </div>

              {/* Aviso Geográfico Enriquecido */}
              <motion.div initial={{ opacity: 0, scale: 0.98 }} whileInView={{ opacity: 1, scale: 1 }} viewport={{ once: true }} className="crystal-card p-12 md:p-20 border-[#f8c8c4]/20 bg-[#f8c8c4]/5 rounded-sm mb-40 flex flex-col md:flex-row gap-12 items-center relative overflow-hidden">
                 <div className="absolute top-0 right-0 p-8 text-[#f8c8c4]/5"><MapPin size={120} strokeWidth={0.5} /></div>
                 <div className="p-8 bg-[#f8c8c4]/10 rounded-full text-[#f8c8c4] shrink-0">
                    <AlertTriangle size={48} strokeWidth={1.5} />
                 </div>
                 <div className="space-y-6 text-center md:text-left relative z-10">
                    <h3 className="heading-serif text-3xl text-white uppercase">{t.careersAdvisoryTitle}</h3>
                    <p className="text-base md:text-xl font-light text-white/70 leading-relaxed max-w-4xl">{t.careersAdvisoryText}</p>
                    <div className="flex flex-wrap gap-6 justify-center md:justify-start pt-6 border-t border-white/5">
                       <a href="https://www.google.com/maps/search/Quarteira,+Loul%C3%A9" target="_blank" rel="noopener noreferrer" className="flex items-center gap-3 text-[10px] font-black uppercase tracking-[0.3em] text-[#f8c8c4] hover:brightness-125 transition-all">
                          <Map size={14} /> Ver Localização da Sede
                       </a>
                    </div>
                 </div>
              </motion.div>

              {/* Vantagens */}
              <div className="mb-40 space-y-24">
                 <div className="text-center">
                    <h3 className="heading-serif text-5xl md:text-7xl text-white uppercase">{t.careersWhyTitle}</h3>
                 </div>
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
                    {[
                      { title: t.careersAdv1, desc: t.careersAdv1Desc, icon: <GraduationCap size={32}/> },
                      { title: t.careersAdv2, desc: t.careersAdv2Desc, icon: <Users size={32}/> },
                      { title: t.careersAdv3, desc: t.careersAdv3Desc, icon: <Award size={32}/> }
                    ].map((adv, idx) => (
                      <div key={idx} className="crystal-card p-12 space-y-8">
                         <div className="text-[#f8c8c4]/40">{adv.icon}</div>
                         <h4 className="text-2xl font-light uppercase text-white">{adv.title}</h4>
                         <p className="text-sm md:text-base font-light text-white/50">{adv.desc}</p>
                      </div>
                    ))}
                 </div>
              </div>

              {/* CTA e Checklist */}
              <div className="crystal-card p-16 md:p-32 rounded-sm text-center border-[#f8c8c4]/10">
                 <h3 className="heading-serif text-5xl md:text-7xl mb-10 text-white uppercase">{t.careersApplyTitle}</h3>
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-8 max-w-4xl mx-auto mb-16 opacity-60">
                    {["Dedicação Total", "Pontualidade Britânica", "Olho para o Detalhe"].map((req, i) => (
                      <div key={i} className="flex items-center justify-center gap-3 text-[10px] font-bold uppercase tracking-[0.2em] text-[#f8c8c4]">
                        <CheckCircle2 size={12} /> {req}
                      </div>
                    ))}
                 </div>
                 <a href={t.careersFormLink} target="_blank" rel="noopener noreferrer" className="btn-serenity inline-flex items-center gap-6 !py-6 !px-12 group-hover:scale-105 transition-transform active:scale-95 shadow-2xl">
                    {t.careersApplyBtn} <ExternalLink size={18}/>
                 </a>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AdminPanel 
        isOpen={isAdminOpen} onClose={() => setIsAdminOpen(false)} onLogout={() => { setIsAuthenticated(false); setIsAdminOpen(false); }}
        siteConfig={siteConfig} setSiteConfig={setSiteConfig} slides={slides} setSlides={setSlides} sectionImages={sectionImages} setSectionImages={setSectionImages} socialLinks={socialLinks} setSocialLinks={setSocialLinks} emailConfig={emailConfig} setEmailConfig={setEmailConfig} notices={notices} setNotices={setNotices} reviews={reviews} setReviews={setReviews} partners={partners} setPartners={setPartners} googleMapsLink={googleMapsLink} setGoogleMapsLink={setGoogleMapsLink} contactPhone={contactPhone} setContactPhone={setContactPhone} addressDetail={addressDetail} setAddressDetail={setAddressDetail} adminUsername={adminUsername} setAdminUsername={setAdminUsername} adminPassword={adminPassword} setAdminPassword={setAdminPassword} activeTab={activeAdminTab} setActiveTab={setActiveAdminTab} t={t} isSyncing={cloudStatus === 'loading'} onResetDefaults={() => { localStorage.clear(); window.location.reload(); }} gasUrl={gasUrl} setGasUrl={setGasUrl} /* Fixed onPublishToCloud return type to satisfy the () => Promise<boolean> requirement. */ onPublishToCloud={async () => { return true; }} cloudStatus={cloudStatus}
      />

      <AnimatePresence>
        {isLoginOpen && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[1200] flex items-center justify-center bg-[#081221]/80 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="crystal-card p-12 max-w-sm w-full">
              <h3 className="heading-serif text-2xl text-center mb-8 uppercase tracking-widest">Acesso Restrito</h3>
              <form onSubmit={handleLogin} className="space-y-6">
                <input placeholder="Utilizador" value={username} onChange={e => setUsername(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 rounded outline-none text-sm" />
                <input placeholder="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 rounded outline-none text-sm" />
                <button type="submit" className="w-full btn-serenity flex items-center justify-center gap-3">Entrar</button>
              </form>
              <button onClick={() => setIsLoginOpen(false)} className="w-full text-[9px] font-bold tracking-[0.3em] text-white/20 uppercase mt-8">Cancelar</button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <footer className="py-24 bg-[#040911] border-t border-white/5">
        <div className="container mx-auto px-8 md:px-16 text-center">
          <div className="flex flex-col items-center gap-12 mb-16">
            <div className="flex items-center gap-4">
              {siteConfig.logoUrl && <img src={siteConfig.logoUrl} alt="Logo" className="w-8 h-8 object-contain" />}
              <h5 className="text-white font-light tracking-[0.4em] text-lg uppercase leading-none">{siteConfig.companyName} <span className="text-[#f8c8c4] block text-[10px] tracking-[0.6em] mt-2">{siteConfig.companySubtitle}</span></h5>
            </div>
            <p className="text-[10px] font-bold tracking-[0.5em] text-white/20 uppercase">{siteConfig.footerNote}</p>
          </div>
          <p className="text-[9px] font-bold tracking-[0.4em] text-white/10 uppercase italic">{siteConfig.footerCopyright}</p>
        </div>
      </footer>
    </div>
  );
};

createRoot(document.getElementById('root')!).render(<App />);
